import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, vec3, float, uniform, MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-row';
  group.position.set(-1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const map = ctx.textureLoader(imageUrl);
  const depthMap = ctx.textureLoader(depthMapUrl);

  const parallaxOffset = uniform(vec3(0, 0, 0));

  const geometry = new THREE.PlaneGeometry(3.2, 0.75, 64, 64);

  const displacementAmount = float(0.08);
  const dispUV = uv();
  const dispSample = texture(depthMap, dispUV).r;
  const displaced = positionLocal.add(
    vec3(parallaxOffset.x, parallaxOffset.y, dispSample.mul(displacementAmount))
  );

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(map, uv());
  material.positionNode = displaced;
  material.metalness = 0.4;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.color = new THREE.Color(colors.paper);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'parallax-stack-plane';
  group.add(mesh);

  // Divider line (thin plane)
  const dividerGeo = new THREE.PlaneGeometry(3.2, 0.01);
  const dividerMat = new THREE.MeshBasicMaterial({ color: colors.ink, transparent: true, opacity: 0.35 });
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.4, 0.001);
  group.add(divider);

  // Title text
  const titleMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Features',
    font: 'display',
    weight: 600,
    size: 0.2,
    color: colors.ink,
    atlas: 0,
    rect: [0, 0, 512, 200],
  });
  titleMesh.position.set(-1.4, 0.1, 0.002);
  group.add(titleMesh);

  // Meta text
  const metaMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Machined-metal engineering, PBR finishes, and kinetic detail.',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: colors.surface,
    atlas: 0,
    rect: [0, 200, 512, 320],
  });
  metaMesh.position.set(-1.4, -0.15, 0.002);
  group.add(metaMesh);

  // Accent edge (hidden until focus)
  const accentGeo = new THREE.PlaneGeometry(3.24, 0.79);
  const accentMat = new THREE.MeshBasicMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    side: THREE.BackSide,
  });
  const accentEdge = new THREE.Mesh(accentGeo, accentMat);
  accentEdge.position.set(0, 0, -0.002);
  group.add(accentEdge);

  let hoverTween = null;
  let pressTween = null;

  const baseY = group.position.y;

  function onHoverEnter() {
    hoverTween && hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(accentMat, { opacity: 0.5, duration: 0.3 });
  }

  function onHoverLeave() {
    hoverTween && hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(accentMat, { opacity: 0, duration: 0.3 });
  }

  function onClick() {
    pressTween && pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (ctx.trpc && ctx.trpc.checkout && ctx.trpc.checkout.begin) {
      ctx.trpc.checkout.begin.mutate({ itemId: 'hub-features' }).then((res) => {
        if (res && res.checkoutUrl && ctx.navigate) {
          ctx.navigate(res.checkoutUrl);
        }
      }).catch(() => {});
    }

    group.dispatchEvent && group.dispatchEvent({ type: 'hub-features.select' });
  }

  group.userData.handlers = {
    onHoverEnter,
    onHoverLeave,
    onClick,
  };

  group.userData.cleanup = () => {
    hoverTween && hoverTween.kill();
    pressTween && pressTween.kill();
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (titleMesh.geometry) titleMesh.geometry.dispose();
    if (titleMesh.material) titleMesh.material.dispose();
    if (metaMesh.geometry) metaMesh.geometry.dispose();
    if (metaMesh.material) metaMesh.material.dispose();
  };

  return group;
}
